import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as i,af as o}from"./chunks/mermaid.YsAH9es0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"领域专用 Code Review Agent：把通用模型变成懂行的项目审查员","description":"阿里云 Kitta 的领域定制方法论拆成 6 张实践卡：项目级专家资产、五阶段分级流水线、上游依赖链完整性检查、子系统知识库与有罪推定审查、验证样本评测闭环、行为作证校准。附一人公司降级做法与数据可核实性分级。","frontmatter":{"title":"领域专用 Code Review Agent：把通用模型变成懂行的项目审查员","description":"阿里云 Kitta 的领域定制方法论拆成 6 张实践卡：项目级专家资产、五阶段分级流水线、上游依赖链完整性检查、子系统知识库与有罪推定审查、验证样本评测闭环、行为作证校准。附一人公司降级做法与数据可核实性分级。","domain":"practice","tags":["code-review","agent","quality-gate","llm-agent"],"outline":[2,3],"navOrder":30,"prev":{"text":"采购与实施方案","link":"/zh/practice/procurement-plan"},"next":false},"headers":[],"relativePath":"zh/practice/agent-handbook/case-code-review.md","filePath":"zh/practice/agent-handbook/case-code-review.md","lastUpdated":1792458633000}'),r={name:"zh/practice/agent-handbook/case-code-review.md"};function n(s,t,l,d,h,c){return i(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="领域专用-code-review-agent-把通用模型变成懂行的项目审查员" tabindex="-1">领域专用 Code Review Agent：把通用模型变成懂行的项目审查员 <a class="header-anchor" href="#领域专用-code-review-agent-把通用模型变成懂行的项目审查员" aria-label="Permalink to &quot;领域专用 Code Review Agent：把通用模型变成懂行的项目审查员&quot;">​</a></h1><blockquote><p><strong>来料</strong>：<a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/06-case-study/%E7%AC%AC25%E7%AB%A0%20%E7%A0%94%E5%8F%91%E6%95%88%E8%83%BD/Kitta%EF%BC%9A%E9%A2%86%E5%9F%9F%E4%B8%93%E7%94%A8%20Code%20Review%20Agent.md" target="_blank" rel="noreferrer">aliyun/ai-agent-handbook 第 25 章 · Kitta：领域专用 Code Review Agent</a></p></blockquote><blockquote><p><strong>本页结论</strong>：AI 写的代码越多，瓶颈越不在「写」——原文说得很直白：「编码已不再受人力限制，但审查的人力并没有同步增长。产能的瓶颈，正在从&quot;写&quot;转移到&quot;审&quot;」。通用 Review 工具在这个位置上会同时栽两跤：<strong>工程行为约束不足</strong>（漏文件、位置漂移、提示词一变质量就抖）和<strong>检查深度不足</strong>（只扫代码本身的缺陷，不懂这个项目什么算问题）。Kitta 给的解法不是换个更强的模型，而是把通用 Agent <strong>领域化</strong>：沉淀项目级专家资产、定制审查流程、建评测与进化闭环。本文把这套方法拆成 6 张可以照做的卡。</p></blockquote><blockquote><p><strong>声明</strong>：本文每条主张都标了来源等级—— <strong>【内部数据】</strong> 阿里云团队自己的生产环境统计，读者无法独立复现，只能作为量级参考； <strong>【可独立复现】</strong> 机制、流程、API 形态，读者在自己仓库内可独立实施； <strong>【外部可核实】</strong> 第三方公开报告，读者可自行核对。 原文末尾自己声明：「本文档为技术能力介绍材料，文中数据来源于内部评测与生产环境统计。」</p></blockquote><hr><h2 id="_0-与现有页面的重叠和插入位置" tabindex="-1">0. 与现有页面的重叠和插入位置 <a class="header-anchor" href="#_0-与现有页面的重叠和插入位置" aria-label="Permalink to &quot;0. 与现有页面的重叠和插入位置&quot;">​</a></h2><h3 id="_0-1-逐页对照" tabindex="-1">0.1 逐页对照 <a class="header-anchor" href="#_0-1-逐页对照" aria-label="Permalink to &quot;0.1 逐页对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现有页面</th><th>现在讲了什么</th><th>与本文的关系</th></tr></thead><tbody><tr><td><code>docs/zh/practice/index.md</code>（企业实践）</td><td>只有两级入口：「1. 先看形势 → Vibe Coding 报告」「2. 再决定怎么买 → 采购与实施方案」</td><td><strong>不重叠，但缺入口。</strong> 该页是目录页，没有任何「怎么落到日常研发节奏」的分支，读者读完前两节后无处可去</td></tr><tr><td><code>docs/practice/ai-efficiency-practice.md</code>（跨平台齐淼树重构）</td><td>「AI 辅助需求到测试全流程」「人工审核节点」「效率提升 40%+、缺陷率下降」（团队反馈口径）</td><td><strong>概念重叠最严重的一页。</strong> 它把「代码审查」列为 AI 覆盖的一个环节和一个人工审核点，但没回答：审查<strong>由谁</strong>做、按<strong>什么标准</strong>判、怎么<strong>证明</strong>它判得对。本文正是这三条的展开</td></tr><tr><td><code>docs/zh/practice/reporter.md</code>（Vibe Coding 报告）</td><td>行业数据、AI 代码占比、对编制的影响</td><td><strong>不重叠</strong>，本文不复述行业判断。若该页已收录 DORA 的 PR 体积数据，本文只做链接</td></tr><tr><td><code>docs/zh/practice/procurement-plan.md</code>（采购与实施）</td><td>预算、模型搭配、合规、责任红线</td><td><strong>不重叠</strong>。其中「代码需强制 Review 且通过 CI/CD 单元测试，开发者为代码质量第一责任人」是本文门禁设计的上游原则</td></tr><tr><td>同章姊妹页（ABACI 内核质量门禁，同期从第 25 章产出）</td><td>定向测试、缺陷模式复用、commit-time 门禁</td><td><strong>互补，建议并列</strong>。ABACI 管「这次改动有没有被验证过」，本文管「这次改动该不该合」。两页应相邻，并互相交叉链接</td></tr></tbody></table><h3 id="_0-2-建议的插入位置" tabindex="-1">0.2 建议的插入位置 <a class="header-anchor" href="#_0-2-建议的插入位置" aria-label="Permalink to &quot;0.2 建议的插入位置&quot;">​</a></h3><ol><li><p><strong><code>index.md</code></strong>：在「### 2. 再决定怎么买」之后新增一节</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### 3. 落地到研发节奏</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">领域专用 Code Review Agent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">./code-review-agent.md</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) — AI 审查怎么落地、按什么标准判、怎么证明它判得对。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">内核质量门禁</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">./kernel-aim-gate.md</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) — 提交即验证：定向测试与缺陷模式复用。</span></span></code></pre></div><p>理由：现有目录停在「买什么」，缺「怎么用起来」。这一节正好把两页挂在同一节下，形成「AI 写 → AI 审 → 提交即验证」的完整链条。</p></li><li><p><strong>新文件路径</strong>：<code>docs/zh/practice/code-review-agent.md</code>，<code>navOrder: 30</code>（<code>reporter</code> = 10，<code>procurement-plan</code> = 20），<code>prev</code> 指向 <code>procurement-plan</code>。若内核质量门禁页先落地，两者 <code>navOrder</code> 取 30 / 40 均可，保持相邻即可。</p></li><li><p><strong><code>ai-efficiency-practice.md</code></strong>：在其「核心要点 3. 人工审核节点」下补一行交叉链接——</p><blockquote><p>人工审核点的判断标准从哪里来、怎么证明 AI 那一段判得对 → 见《领域专用 Code Review Agent》。</p></blockquote><p>这行是本页与该页唯一必要的连接，不要在两页里各写一遍审查流程。</p></li><li><p><strong>注意语言树</strong>：该文件在 <code>docs/practice/</code>（英文站 <code>/practice/</code>），而本文在 <code>docs/zh/practice/</code>。中文站的 <code>index.md</code> 目前只在末段用一句「英文站还有……团队提效：Practice」指向英文站，<strong>没有直接链到这一篇</strong>。所以：</p><ul><li>在英文站那一页加回链时，要用绝对路径 <code>/zh/practice/code-review-agent</code>，不能用相对路径 <code>../zh/...</code>；</li><li>想让中文读者看到这篇对照内容，需要额外决定是建一个 <code>docs/zh/practice/</code> 下的对应页，还是接受“跨语言站不互链”。<strong>建议本次不动</strong>——本轮只交草稿，改动留给发版时统一处理。</li></ul></li></ol><hr><h2 id="_1-实践卡-·-用「项目级专家资产」替代通用最佳实践" tabindex="-1">1. 实践卡 · 用「项目级专家资产」替代通用最佳实践 <a class="header-anchor" href="#_1-实践卡-·-用「项目级专家资产」替代通用最佳实践" aria-label="Permalink to &quot;1. 实践卡 · 用「项目级专家资产」替代通用最佳实践&quot;">​</a></h2><h3 id="_1-1-要解决的问题" tabindex="-1">1.1 要解决的问题 <a class="header-anchor" href="#_1-1-要解决的问题" aria-label="Permalink to &quot;1.1 要解决的问题&quot;">​</a></h3><p>通用 AI Review 在两个维度同时失灵。原文的拆解很值得抄进设计文档：</p><ul><li><strong>工程行为约束不足</strong>：「覆盖不全、位置漂移、效果不稳定——变更较大时倾向于只评审部分文件导致遗漏，报告的问题与实际代码位置对不上，评审质量随提示词的细微差异大幅波动。」</li><li><strong>检查深度不足</strong>：「缺乏对审查项目的语义理解，规则浮于表面——对每个项目、每次评审一视同仁，只能扫描代码本身的缺陷，感知不到项目特有的审查需求。」</li></ul><p>落到具体症状：模型能识别「这段代码有 SQL 拼接」，但识别不了「这个仓库不允许引入新的同步 IO」。</p><h3 id="_1-2-具体做法" tabindex="-1">1.2 具体做法 <a class="header-anchor" href="#_1-2-具体做法" aria-label="Permalink to &quot;1.2 具体做法&quot;">​</a></h3><p><strong>【可独立复现】</strong> 从本仓库的真实历史里提炼资产，四步走：<strong>采集关联 → 规整去噪 → 语义解析 → 隔离复现</strong>。原文特别强调第四步：「其中&quot;隔离复现&quot;是为了让每一条缺陷模式与预期结论都可验证、经得起追问，而不是把噪音当经验。」</p><p>产物只有两类，但两类都不能少：</p><table tabindex="0"><thead><tr><th>资产</th><th>内容</th><th>回答的问题</th></tr></thead><tbody><tr><td><strong>评判标准</strong></td><td>评审原则、缺陷模式、项目惯例</td><td>「按什么标准判」</td></tr><tr><td><strong>验证样本</strong></td><td>问题样本、正常样本、预期结论</td><td>「判得对不对如何度量」</td></tr></tbody></table><p>关键在于这两类是<strong>成对</strong>的：只有标准没有样本，你无法证明改了提示词之后是变好还是变坏（这正是卡 5 要接的问题）。</p><p><strong>最小可复现形态（个人版，不需要做 pipeline）</strong>：翻 git log 和 PR 评论，挑 20–50 条「过去真的吵过架的改动」+ 10–20 条「明确 LGTM、一行没改的改动」，写成两份文件：<code>review-rubric.md</code>（判定标准）+ <code>review-samples/</code>（样本与预期结论）。这就是专家资产的最小形态，一晚上能建好。</p><h3 id="_1-3-前置条件" tabindex="-1">1.3 前置条件 <a class="header-anchor" href="#_1-3-前置条件" aria-label="Permalink to &quot;1.3 前置条件&quot;">​</a></h3><ul><li>仓库有至少 3 个月可追溯的 PR / issue / commit 历史（否则只能从开源同类项目的惯例起步）。</li><li>至少有一个人能把「什么算问题」写清楚——这项工作无法外包给模型，它就是领域知识的载体。</li><li>样本需要人工确认一次（模型可以起草，人只做是/否）。</li></ul><h3 id="_1-4-适用边界" tabindex="-1">1.4 适用边界 <a class="header-anchor" href="#_1-4-适用边界" aria-label="Permalink to &quot;1.4 适用边界&quot;">​</a></h3><ul><li><strong>适用</strong>：任何「有历史、有惯例、有隐性标准」的仓库——企业内部服务、长期维护的 SDK、基础软件。</li><li><strong>不适用</strong>：绿地项目（没有历史可提炼）、一次性脚本、几百行的个人项目（资产维护成本高于收益）。</li><li><strong>半适用</strong>：全新仓库但有强上游/标杆项目——可以从上游的评审惯例起步，但必须标注「这是外来的标准，不是我们的」。</li></ul><h3 id="_1-5-反例-失败模式" tabindex="-1">1.5 反例 / 失败模式 <a class="header-anchor" href="#_1-5-反例-失败模式" aria-label="Permalink to &quot;1.5 反例 / 失败模式&quot;">​</a></h3><ul><li><strong>把通用清单当专家资产</strong>。原文明确反对「泛泛的&quot;最佳实践&quot;」。CWE 全文、OWASP Top 10、某公司内部规范粘贴进来，长得像资产，实则对每个项目一视同仁，回到「检查深度不足」。</li><li><strong>跳过隔离复现</strong>。从旧评论里直接抓结论，会把当年误判的结论一起固化，并给它盖上「我们一直这么做」的权威。</li><li><strong>只写标准不写样本</strong>。评审质量从此只能靠感觉，而感觉正是原文要反对的：「用户说&quot;好&quot;不一定是真的好，Agent 自我感觉良好更是靠不住——没有客观的评估与进化闭环，信任就无从建立。」</li><li><strong>资产只增不减</strong>。半年后 rubric 里一半条目已被代码改动作废，Agent 会开始按废标准报警，团队直接关掉通知。</li></ul><h3 id="_1-6-可验证的效果指标" tabindex="-1">1.6 可验证的效果指标 <a class="header-anchor" href="#_1-6-可验证的效果指标" aria-label="Permalink to &quot;1.6 可验证的效果指标&quot;">​</a></h3><ul><li><strong>分类型意见采纳率</strong>（原文口径）：回合补丁一致性检查 70.4%，自研 PR 代码质量意见 41.8%。<strong>【内部数据】</strong></li><li><strong>同类问题复发率</strong>：某个已被写进 rubric 的缺陷类型，在后续 20 个 PR 里再出现的次数。</li><li><strong>人工复核时间</strong>：Maintainer 花在「确认这条意见对不对」上的时间，而不是花在逐行读 diff 上。</li></ul><h3 id="_1-7-原文逐字引用" tabindex="-1">1.7 原文逐字引用 <a class="header-anchor" href="#_1-7-原文逐字引用" aria-label="Permalink to &quot;1.7 原文逐字引用&quot;">​</a></h3><blockquote><p>「通用模型见过很多代码，但未必懂内核的锁语义，也未必懂编译器的中间表示约定——而这些恰恰是评审结论对错的关键。」</p></blockquote><blockquote><p>「领域知识不是凭空来的，而是从真实历史中提炼的。」</p></blockquote><hr><h2 id="_2-实践卡-·-五阶段分级流水线-先分类-再规范-再依赖-最后质量" tabindex="-1">2. 实践卡 · 五阶段分级流水线：先分类，再规范，再依赖，最后质量 <a class="header-anchor" href="#_2-实践卡-·-五阶段分级流水线-先分类-再规范-再依赖-最后质量" aria-label="Permalink to &quot;2. 实践卡 · 五阶段分级流水线：先分类，再规范，再依赖，最后质量&quot;">​</a></h2><h3 id="_2-1-要解决的问题" tabindex="-1">2.1 要解决的问题 <a class="header-anchor" href="#_2-1-要解决的问题" aria-label="Permalink to &quot;2.1 要解决的问题&quot;">​</a></h3><p>一次性把所有检查糊在一个大 review 里，会同时踩三个坑：<strong>成本浪费</strong>（对自研补丁跑回合补丁专属检查）、<strong>报告淹没</strong>（所有问题同级，没人看）、<strong>定位困难</strong>（评论挂不到具体行）。</p><h3 id="_2-2-具体做法" tabindex="-1">2.2 具体做法 <a class="header-anchor" href="#_2-2-具体做法" aria-label="Permalink to &quot;2.2 具体做法&quot;">​</a></h3><p><strong>【可独立复现】</strong> Kitta 在 ANCK 上跑的是一条五阶段流水线，触发方式是提交 PR 或在评论里输入 <code>/check-code-review</code>。原文的顺序设计值得直接照搬：</p><table tabindex="0"><thead><tr><th>阶段</th><th>做什么</th><th>为什么放这个位置</th></tr></thead><tbody><tr><td><strong>Stage 1. PR 分类</strong></td><td>判断纯自研补丁还是回合补丁</td><td>分类决定后续检查范围</td></tr><tr><td><strong>Stage 2. PR / Commit Message 规范检查</strong></td><td>基于社区规范文档检查描述、标题、commit message</td><td>最便宜、拦得最多</td></tr><tr><td><strong>Stage 3. 补丁完整性检查</strong></td><td>追上游依赖链，找遗漏的 Fixes</td><td>只对回合补丁执行</td></tr><tr><td><strong>Stage 4. 补丁回合一致性检查</strong></td><td>三层对比上游原补丁</td><td>只对声明了上游来源的补丁执行</td></tr><tr><td><strong>Stage 5. 代码质量审查</strong></td><td>通用质量维度，按严重程度分级</td><td>最后兜底</td></tr></tbody></table><p>三个关键机制：</p><ol><li><strong>分类先于检查</strong>。Stage 1 的判据极简：「如果 Commit 中存在类似 <code>commit xxxx upstream</code> 的上游补丁声明，则归为回合补丁。」原文点明收益：「纯自研补丁不会执行补丁完整性检查和回合一致性检查，避免不必要的开销。」这就是一个十行的正则，收益是砍掉 2/5 的审查开销。</li><li><strong>没有问题则不报告</strong>。Stage 2 原文：「没有问题则不报告；有问题则给出 Message 规范建议，供开发者参考。」——<strong>沉默是默认态</strong>，这是「克制打扰」在工程上的落点。</li><li><strong>结论用分层标签输出，而不是一段自然语言</strong>。Stage 4 的差异分级是 <code>consistent</code> → <code>text-inconsistent</code> → <code>semantic-inconsistent</code> → <code>inconsistent</code>；Stage 5 的严重度分级是 <code>Critical</code> / <code>Medium / Low</code>，没风险直接给 <code>LGTM</code>。</li></ol><h3 id="_2-3-前置条件" tabindex="-1">2.3 前置条件 <a class="header-anchor" href="#_2-3-前置条件" aria-label="Permalink to &quot;2.3 前置条件&quot;">​</a></h3><ul><li>有 PR 模板和 CI 触发能力（GitHub Actions / GitLab CI 等价物均可）。</li><li>bot 有仓库读权限；Stage 3–4 还需要上游仓库或邮件列表的读权限。</li><li>严重度标签有明确定义——否则分级只是换了个词。</li></ul><h3 id="_2-4-适用边界" tabindex="-1">2.4 适用边界 <a class="header-anchor" href="#_2-4-适用边界" aria-label="Permalink to &quot;2.4 适用边界&quot;">​</a></h3><ul><li><strong>适用</strong>：多提交、多人、有人工 maintainer 的仓库。</li><li><strong>可裁剪</strong>：单模块小仓可合并 Stage 3+4；没有上游同步场景的直接删掉 Stage 1 的分类和 Stage 3、4，只留 Stage 2 + 5。</li><li><strong>不适用</strong>：一次性脚本、无人 review 的个人实验分支。</li></ul><h3 id="_2-5-反例-失败模式" tabindex="-1">2.5 反例 / 失败模式 <a class="header-anchor" href="#_2-5-反例-失败模式" aria-label="Permalink to &quot;2.5 反例 / 失败模式&quot;">​</a></h3><ul><li><strong>不做分类就全量跑</strong>。所有检查无差别执行，成本翻倍，且回合专属的检查在自研补丁上必然误报。</li><li><strong>所有问题同一优先级</strong>。Critical 和「命名不够好」混在一张清单里，前者会被淹没。<strong>检验方法</strong>：如果 Critical 与 Medium 的采纳率相近，说明分级是装饰性的，该重做。</li><li><strong>评论不落行</strong>。原文批评过「报告的问题与实际代码位置对不上」——不落行的评论等于让开发者手工二次定位，等于没审。</li><li><strong>Stage 2 变成噪音源</strong>。规范检查最容易被写成挑刺清单，「没有问题则不报告」这条纪律必须写进代码，不能靠自觉。</li></ul><h3 id="_2-6-可验证的效果指标" tabindex="-1">2.6 可验证的效果指标 <a class="header-anchor" href="#_2-6-可验证的效果指标" aria-label="Permalink to &quot;2.6 可验证的效果指标&quot;">​</a></h3><ul><li><strong>单 PR 审查耗时</strong>（含模型调用与排队），分自研 / 回合两类分别统计。</li><li><strong>分层采纳率差值</strong>：<code>Critical</code> 与 <code>Medium / Low</code> 的采纳率之差。差值小 = 分级失效。</li><li><strong>Maintainer 追问回合数</strong>：原文称「大幅减少了 Maintainer 反复追问、来回确认的回合数」，但<strong>未给出具体数字</strong>——读者应把它当成待验证假设，自己在 10 个 PR 上量一次。<strong>【内部数据（无量化）】</strong></li></ul><h3 id="_2-7-原文逐字引用" tabindex="-1">2.7 原文逐字引用 <a class="header-anchor" href="#_2-7-原文逐字引用" aria-label="Permalink to &quot;2.7 原文逐字引用&quot;">​</a></h3><blockquote><p>「开发者提交 PR 或在评论中输入 <code>/check-code-review</code> 后，审查任务即被触发；整个流程先分类、再检查规范与依赖、最后落到代码质量，层层递进。」</p></blockquote><blockquote><p>「Kitta 将审查出的问题按严重程度分为 <code>Critical</code>、<code>Medium / Low</code>，Critical 问题通常会以内联评论定位到具体代码行，需要开发者处理或明确是否为误报；未发现风险则给出 <code>LGTM</code>。」</p></blockquote><hr><h2 id="_3-实践卡-·-上游依赖链完整性检查-「该带什么」比「改了什么」更重要" tabindex="-1">3. 实践卡 · 上游依赖链完整性检查（「该带什么」比「改了什么」更重要） <a class="header-anchor" href="#_3-实践卡-·-上游依赖链完整性检查-「该带什么」比「改了什么」更重要" aria-label="Permalink to &quot;3. 实践卡 · 上游依赖链完整性检查（「该带什么」比「改了什么」更重要）&quot;">​</a></h2><h3 id="_3-1-要解决的问题" tabindex="-1">3.1 要解决的问题 <a class="header-anchor" href="#_3-1-要解决的问题" aria-label="Permalink to &quot;3.1 要解决的问题&quot;">​</a></h3><p>回合 / backport 场景有一个通用 Review 抓不到的缺陷类型：<strong>这次改动本身是对的，但它依赖的其他补丁没跟过来</strong>。于是下游重新引入了上游早就修掉的漏洞——而且代码看起来完全正常。</p><h3 id="_3-2-具体做法" tabindex="-1">3.2 具体做法 <a class="header-anchor" href="#_3-2-具体做法" aria-label="Permalink to &quot;3.2 具体做法&quot;">​</a></h3><p><strong>【可独立复现】</strong> Kitta 的检查是一个三段式判定，Stage 3 原文写得很清楚：</p><blockquote><p>「按&quot;检索上游 Fixes → 判断是否在 PR 中 → 判断是否在下游仓库已存在&quot;的流程排查遗漏。」</p></blockquote><p>输出必须是<strong>三类互斥</strong>的结论，而不是一个布尔值：</p><table tabindex="0"><thead><tr><th>输出</th><th>含义</th><th>处理</th></tr></thead><tbody><tr><td><code>无遗漏 Fixes</code></td><td>无需补充</td><td>放行</td></tr><tr><td><code>已合入的 Fixes 补丁</code></td><td>相关修复已存在于下游仓库</td><td>放行（且要能指出是哪个 commit）</td></tr><tr><td><code>遗漏的 Fixes 补丁</code></td><td>需要开发者补充</td><td>拦截，「防止已知漏洞被重新引入下游」</td></tr></tbody></table><p>一致性检查同理，分三层递进：<strong>基础对比</strong>（改了哪些文件、哪些代码块）→ <strong>上下文对比</strong>（引用的符号、函数、变量定义是否一致、是否做了合理适配）→ <strong>语义对比</strong>（由 LLM 判断上下游是否实现了相同功能）。</p><p>补丁完整性检查在 3.1 节被称为「采用四阶段遗漏 Fixes 检索流程」，而 Stage 3 正文只展开了三步。<strong>两处口径不一致，原文未说明第四步是什么</strong>；读者照做时按三步起步即可，不要卡在这里。</p><h3 id="_3-3-前置条件" tabindex="-1">3.3 前置条件 <a class="header-anchor" href="#_3-3-前置条件" aria-label="Permalink to &quot;3.3 前置条件&quot;">​</a></h3><ul><li>有可访问的上游源：公开 Git 仓库、邮件列表，或至少能拉到上游 git 历史。</li><li>commit message 里有稳定追溯线索：<code>commit xxxx upstream</code>、<code>Fixes:</code> 标签、或可解析的原始 commit id。<strong>没有线索就得先补线索</strong>，否则这一步没法自动化。</li></ul><h3 id="_3-4-适用边界" tabindex="-1">3.4 适用边界 <a class="header-anchor" href="#_3-4-适用边界" aria-label="Permalink to &quot;3.4 适用边界&quot;">​</a></h3><ul><li><strong>适用</strong>：内核回合、cherry-pick / backport 修复、把上游配置或 vendor 目录同步进内仓、从上游抄安全补丁。</li><li><strong>可外推</strong>：任何「从别处搬代码进来」的场景——包括抄开源库源码、升级 vendored 依赖、迁移老代码到新框架。依赖闭包的逻辑一样。</li><li><strong>不适用</strong>：纯自研、无上游的模块；上游不可访问的闭源组件（此时退化为「本仓库同类修复清单」人工 grep）。</li></ul><h3 id="_3-5-反例-失败模式" tabindex="-1">3.5 反例 / 失败模式 <a class="header-anchor" href="#_3-5-反例-失败模式" aria-label="Permalink to &quot;3.5 反例 / 失败模式&quot;">​</a></h3><ul><li><strong>只问「这次改了什么」，不问「该带什么」</strong>。这是回合场景最典型的漏判，也是 Stage 3 存在的全部理由。</li><li><strong>把「已合入」和「未合入」混成一个布尔输出</strong>。开发者无法区分「不需要处理」和「没查到」，噪音直接翻倍。</li><li><strong>把「逐行都对」当成一致</strong>。原文对一致性检查的方案描述里有一句是对所有 Review 的警告：「方案上先微观溯源、比对补丁级差异，再宏观评估整体功能是否一致，避免&quot;逐行都对、整体变了&quot;的漏判。」适配改动越多的回合，越容易出现「每个 hunk 都对、合起来语义变了」。</li><li><strong>依赖 LLM 去数 Fixes 标签</strong>。这类工作应该由脚本按 git 历史确定性完成，交给模型只会引入不稳定性。</li></ul><h3 id="_3-6-可验证的效果指标" tabindex="-1">3.6 可验证的效果指标 <a class="header-anchor" href="#_3-6-可验证的效果指标" aria-label="Permalink to &quot;3.6 可验证的效果指标&quot;">​</a></h3><ul><li><strong>遗漏检出率</strong>：在已合入的历史 PR 上回溯跑一遍，看能捞出多少「当时漏带的补丁」——这是建立信任的关键实验，成本很低。</li><li><strong>补齐率</strong>：被报遗漏的 PR，最终有多少真的补上了。</li><li><strong>回合补丁一致性意见采纳率 / 准确率</strong>：原文为 70.4% / 99.8%。<strong>【内部数据】</strong>。这个数字远高于自研 PR 场景，恰好说明：<strong>确定性可判的检查，AI 的意见才敢当真</strong>。</li></ul><h3 id="_3-7-原文逐字引用" tabindex="-1">3.7 原文逐字引用 <a class="header-anchor" href="#_3-7-原文逐字引用" aria-label="Permalink to &quot;3.7 原文逐字引用&quot;">​</a></h3><blockquote><p>「检查结果分为三类：<code>无遗漏 Fixes</code> 表示无需补充；<code>已合入的 Fixes 补丁</code> 说明相关修复已存在于下游仓库；<code>遗漏的 Fixes 补丁</code> 则要求开发者补充，防止已知漏洞被重新引入下游。」</p></blockquote><blockquote><p>「基础对比看修改的文件和代码块是否一致；上下文对比看引用的符号、函数、变量定义是否一致、是否做了合理适配；语义对比则通过 LLM 判断上下游补丁是否实现了相同功能和语义。」</p></blockquote><hr><h2 id="_4-实践卡-·-按子系统切知识库-「有罪推定—调用链分析—自我辩论」" tabindex="-1">4. 实践卡 · 按子系统切知识库 + 「有罪推定—调用链分析—自我辩论」 <a class="header-anchor" href="#_4-实践卡-·-按子系统切知识库-「有罪推定—调用链分析—自我辩论」" aria-label="Permalink to &quot;4. 实践卡 · 按子系统切知识库 + 「有罪推定—调用链分析—自我辩论」&quot;">​</a></h2><h3 id="_4-1-要解决的问题" tabindex="-1">4.1 要解决的问题 <a class="header-anchor" href="#_4-1-要解决的问题" aria-label="Permalink to &quot;4.1 要解决的问题&quot;">​</a></h3><p>同一份 checklist 覆盖整个仓库，等于没有 checklist。内核的不同子系统关注点差异极大（并发子系统看锁语义，文件系统看崩溃一致性，网络栈看协议状态机）；用同一套标准审，只会得到泛泛的「最佳实践」。</p><h3 id="_4-2-具体做法" tabindex="-1">4.2 具体做法 <a class="header-anchor" href="#_4-2-具体做法" aria-label="Permalink to &quot;4.2 具体做法&quot;">​</a></h3><p><strong>【可独立复现】</strong> 两件事叠加。</p><p><strong>（a）知识库做子领域拆分</strong>。原文：「内核不同子系统的评审关注点差异很大，按子系统组织专用知识库，让评审贴合各子领域的真实惯例」。</p><p>落地形态：<strong>目录即子系统</strong>。先把仓库按目录划成 3–6 个子系统，每个子系统一份 <code>checklist.md</code>，由这个子系统的 owner 维护。Review 时先分类到子系统，再加载对应清单——这一步用规则做（看 diff 落在哪些目录），不需要模型。</p><p><strong>（b）深度审查走三段流程</strong>。原文定义的流程是「有罪推定—全栈调用链分析—自我辩论」：</p><blockquote><p>「引入&quot;有罪推定—全栈调用链分析—自我辩论&quot;的审查流程：先假设代码有问题，沿全栈调用链追语义，再自我辩论验证结论，加强对内核常见关键代码风险的识别深度。」</p></blockquote><p>拆成 Agent 可执行的动作：</p><table tabindex="0"><thead><tr><th>段</th><th>动作</th><th>对抗的错误</th></tr></thead><tbody><tr><td>有罪推定</td><td>不问「有没有 bug」，直接问「这段改动最可能引入什么后果」</td><td>默认收束到「看起来对」</td></tr><tr><td>全栈调用链分析</td><td>沿调用者/被调用者追语义，找可达路径上的约束</td><td>孤立看 diff 片段，漏掉跨模块不变量</td></tr><tr><td>自我辩论</td><td>生成「支持有缺陷」「支持无缺陷」两段论证，再由结论环节按证据裁决</td><td>单次采样幻觉（一次生成说没 bug 就信）</td></tr></tbody></table><p><strong>硬约束（个人版最重要的一条）</strong>：任何缺陷结论必须附带<strong>具体行号 + 一个能触发的反例场景</strong>，否则不许输出。这一条把幻觉率压下来的成本，比自我辩论低一个数量级。</p><h3 id="_4-3-前置条件" tabindex="-1">4.3 前置条件 <a class="header-anchor" href="#_4-3-前置条件" aria-label="Permalink to &quot;4.3 前置条件&quot;">​</a></h3><ul><li>能拿到调用关系：语言服务器、cscope / clangd、或者退化的 grep 兜底。</li><li>仓库目录结构本身有语义（如果所有代码平铺在一个目录里，先做子系统划分）。</li><li>有一个「强制输出格式」机制（schema / 模板），否则约束会被模型忽略。</li></ul><h3 id="_4-4-适用边界" tabindex="-1">4.4 适用边界 <a class="header-anchor" href="#_4-4-适用边界" aria-label="Permalink to &quot;4.4 适用边界&quot;">​</a></h3><ul><li><strong>适用</strong>：跨模块调用密集、有隐性不变量的系统（基础设施、SDK、平台服务）。</li><li><strong>不适用</strong>：几百行的小项目——调用链分析的成本大于收益；纯 UI / 文案 / 配置生成——语义链太浅；能被编译器 / linter / 类型系统<strong>确定判定</strong>的问题（能否编译、类型对不对），<strong>不要交给 LLM</strong>。</li><li><strong>谨慎适用</strong>：对时延敏感的 CI——三段流程意味着 3 倍以上模型调用。</li></ul><h3 id="_4-5-反例-失败模式" tabindex="-1">4.5 反例 / 失败模式 <a class="header-anchor" href="#_4-5-反例-失败模式" aria-label="Permalink to &quot;4.5 反例 / 失败模式&quot;">​</a></h3><ul><li><strong>把「有罪推定」做成「默认报缺陷」</strong>。有罪推定是搜索策略，不是结论策略。原文自己的数据就是警示：自研 PR 场景准确率只有 73.6%，即每四条意见里有一条不准。<strong>【内部数据】</strong></li><li><strong>用有罪推定审确定性可判的问题</strong>。「这段代码能否编译」不是 LLM 的强项，让它去答只会引入抖动。</li><li><strong>不加载子系统知识库就开审</strong>。等于退回通用 Review，只是套了个「深度审查」的名字。</li><li><strong>自我辩论退化成让模型自我复读</strong>。两次调用用同一个 prompt、同一个采样种子，等于一次调用。</li></ul><h3 id="_4-6-可验证的效果指标" tabindex="-1">4.6 可验证的效果指标 <a class="header-anchor" href="#_4-6-可验证的效果指标" aria-label="Permalink to &quot;4.6 可验证的效果指标&quot;">​</a></h3><ul><li><strong>按缺陷类型 / 子系统的准确率矩阵</strong>。原文正是靠「与 sashiko、review-prompts、qoder 等 SOTA 方案横向对比」，「能够清楚看到自身在特定缺陷类型、特定子系统上的差距」，再把差距转成迭代优先级。<strong>【可独立复现】</strong>——矩阵比总分有用得多。</li><li><strong>误报确认率</strong>：Stage 5 要求「开发者处理或明确是否为误报」，这个「明确为误报」按钮的点击率就是误报率的直接度量。</li><li><strong>有效意见密度</strong> = 采纳意见数 / 总意见数。低于某个值就该收窄触发条件，而不是换更强的模型。</li></ul><h3 id="_4-7-原文逐字引用" tabindex="-1">4.7 原文逐字引用 <a class="header-anchor" href="#_4-7-原文逐字引用" aria-label="Permalink to &quot;4.7 原文逐字引用&quot;">​</a></h3><blockquote><p>「先假设代码有问题，沿全栈调用链追语义，再自我辩论验证结论，加强对内核常见关键代码风险的识别深度。」</p></blockquote><blockquote><p>「引入 sashiko、review-prompts、qoder 等多个 SOTA 代码审查工作参与横向评估，用对比结果指导 Skills 进化。」</p></blockquote><hr><h2 id="_5-实践卡-·-先有验证样本-才谈得上「进化」" tabindex="-1">5. 实践卡 · 先有验证样本，才谈得上「进化」 <a class="header-anchor" href="#_5-实践卡-·-先有验证样本-才谈得上「进化」" aria-label="Permalink to &quot;5. 实践卡 · 先有验证样本，才谈得上「进化」&quot;">​</a></h2><h3 id="_5-1-要解决的问题" tabindex="-1">5.1 要解决的问题 <a class="header-anchor" href="#_5-1-要解决的问题" aria-label="Permalink to &quot;5.1 要解决的问题&quot;">​</a></h3><p>没有客观评估时，改进是盲改。原文把这个叫「信任边界模糊」，说得很准：</p><blockquote><p>「用户说&quot;好&quot;不一定是真的好，Agent 自我感觉良好更是靠不住——没有客观的评估与进化闭环，信任就无从建立。」</p></blockquote><p>具体症状：今天改了一版 prompt，感觉输出更好了；下周 review 效果下降，你分不清是 prompt 退化、代码难度变了，还是随机波动。</p><h3 id="_5-2-具体做法" tabindex="-1">5.2 具体做法 <a class="header-anchor" href="#_5-2-具体做法" aria-label="Permalink to &quot;5.2 具体做法&quot;">​</a></h3><p><strong>【可独立复现】</strong> 双侧机制：</p><p><strong>离线侧</strong>——「用验证样本做隔离评测，根据结果反思进化，持续校准 Agent 的判断标准。」关键在「<strong>隔离</strong>」：评测样本不能和优化样本重叠，否则分数是泄漏出来的。</p><p><strong>评估集的三类来源</strong>（这是整套方法里最值得抄的一条设计）：</p><table tabindex="0"><thead><tr><th>来源</th><th>作用</th><th>对应原文理由</th></tr></thead><tbody><tr><td>真实社区评审过程（LKML）</td><td>对齐真实 reviewer 的判断标准</td><td>「问题分布均匀、真实性强」</td></tr><tr><td>单 commit—单 issue 精确对应（sashiko benchmark）</td><td>让改进方向足够聚焦</td><td>「提供了严格的单 commit—单 issue 映射」</td></tr><tr><td>自家仓库数据</td><td>把评估拉回真实服务语境</td><td>「把评估拉回到 Kitta 实际服务的仓库语境中」</td></tr></tbody></table><p>三类互相制衡：只用自己的数据会过拟合，只用外部数据会脱离语境，只看真实评审过程则缺精确标签。</p><p><strong>最小可复现版本</strong>：30–50 条带标准答案的样本，每条 = <code>diff 摘要 + 上下文 + 预期结论 + 判这个结论的理由</code>。规则变更时重跑，跑 precision / recall，不看「感觉」。</p><h3 id="_5-3-前置条件" tabindex="-1">5.3 前置条件 <a class="header-anchor" href="#_5-3-前置条件" aria-label="Permalink to &quot;5.3 前置条件&quot;">​</a></h3><ul><li>有人愿意标注样本。<strong>可行路径</strong>：让模型先按 rubric 起草结论与理由，人只做确认（每条 1 分钟）。不要从零人工写。</li><li>评测集必须版本化。rubric 改了，样本也要跟着标版本，否则分数不可比。</li><li>样本要覆盖「正常样本」——只有问题样本会让 recall 好看、precision 一片狼藉。</li></ul><h3 id="_5-4-适用边界" tabindex="-1">5.4 适用边界 <a class="header-anchor" href="#_5-4-适用边界" aria-label="Permalink to &quot;5.4 适用边界&quot;">​</a></h3><ul><li><strong>适用</strong>：任何要长期迭代的 review agent / prompt。</li><li><strong>不适用</strong>：样本 &lt; 20 条（指标波动大于收益）；只做一次性接入的项目。</li><li><strong>注意</strong>：样本分布必须跟着代码演进更新，否则评测集会系统性放过新出现的问题类型。</li></ul><h3 id="_5-5-反例-失败模式" tabindex="-1">5.5 反例 / 失败模式 <a class="header-anchor" href="#_5-5-反例-失败模式" aria-label="Permalink to &quot;5.5 反例 / 失败模式&quot;">​</a></h3><ul><li><strong>拿优化数据当评测集</strong>。用同一批样本既调 prompt 又测效果，分数必然虚高。这是自评体系最常见的自欺。</li><li><strong>只统计「提了多少个问题」当质量</strong>。数量可以刷。真正该看的是采纳率和准确率。</li><li><strong>样本全是自研补丁</strong>。回合补丁那类确定性检查的高准确率会掩盖开放性质量意见的弱项。</li><li><strong>评测分数与线上采纳率长期背离</strong>。这是评测集失真的最强信号，一旦出现就重采样本。</li></ul><h3 id="_5-6-可验证的效果指标" tabindex="-1">5.6 可验证的效果指标 <a class="header-anchor" href="#_5-6-可验证的效果指标" aria-label="Permalink to &quot;5.6 可验证的效果指标&quot;">​</a></h3><ul><li><strong>评测集上的准确率 / 召回率</strong>，以及<strong>每次改动 prompt 后的净变化值</strong>（±1% 属于噪声，要看多次）。</li><li><strong>评测分与线上采纳率的相关性</strong>。两者应当同向；不同向说明评测集已经不代表真实分布。</li><li><strong>隔离纪律</strong>：优化样本与评测样本的交集必须为空，这条最好在 CI 里做成检查。</li></ul><h3 id="_5-7-原文逐字引用" tabindex="-1">5.7 原文逐字引用 <a class="header-anchor" href="#_5-7-原文逐字引用" aria-label="Permalink to &quot;5.7 原文逐字引用&quot;">​</a></h3><blockquote><p>「基于三类来源收集数据——LKML（真实社区 Reviewer 的评审过程，问题分布均匀、真实性强）、sashiko benchmark（单 commit—单 issue 精确对应）、龙蜥 Gitee 社区数据」</p></blockquote><blockquote><p>「用验证样本做隔离评测，根据结果反思进化，持续校准 Agent 的判断标准。」</p></blockquote><hr><h2 id="_6-实践卡-·-行为作证-用「代码改了什么」校准-而不是听人夸" tabindex="-1">6. 实践卡 · 行为作证：用「代码改了什么」校准，而不是听人夸 <a class="header-anchor" href="#_6-实践卡-·-行为作证-用「代码改了什么」校准-而不是听人夸" aria-label="Permalink to &quot;6. 实践卡 · 行为作证：用「代码改了什么」校准，而不是听人夸&quot;">​</a></h2><h3 id="_6-1-要解决的问题" tabindex="-1">6.1 要解决的问题 <a class="header-anchor" href="#_6-1-要解决的问题" aria-label="Permalink to &quot;6.1 要解决的问题&quot;">​</a></h3><p>用户反馈稀疏、有偏，而且最有信息量的那批反馈根本不存在——<strong>大部分人只是默默无视</strong>。如果把「没人反对」当成「大家认可」，Agent 会朝着沉默的幻觉方向进化。</p><h3 id="_6-2-具体做法" tabindex="-1">6.2 具体做法 <a class="header-anchor" href="#_6-2-具体做法" aria-label="Permalink to &quot;6.2 具体做法&quot;">​</a></h3><p><strong>【可独立复现】</strong> 把评估主信号从「人说了什么」换成「代码改了什么」。原文的表述：</p><blockquote><p>「不把开发者的默默无视当成认可，不看用户说什么，看&quot;代码改了什么&quot;：通过置信度熔断与追踪真实代码变更，基于客观变更驱动审查和模型迭代。」</p></blockquote><p>三个可落地的机制：</p><ol><li><strong>意见 ID + 变更回查</strong>。每条 review 意见带一个稳定锚点（内联评论 id）。PR 后续有 commit/push 时，回查这些行是否被修改 → 得到自动化的「采纳率」口径。这正是原文线上评估框架的作用：「结合 Review 采纳率持续监控、知识更新、迭代校准与阈值调整」。</li><li><strong>置信度熔断</strong>。低置信度的意见不升级为门禁，只作为提示；置信度高且类别硬（安全漏洞、破坏性变更）才拦 CI。原文的底线划分是：「对安全漏洞和破坏坚决拦截 CI 流程，这是底线；其余问题分级呈现、仅作提示」。</li><li><strong>阈值是调出来的，不是拍的</strong>。随着线上数据积累，持续调「哪些类别在什么置信度下才拦截」。</li></ol><h3 id="_6-3-前置条件" tabindex="-1">6.3 前置条件 <a class="header-anchor" href="#_6-3-前置条件" aria-label="Permalink to &quot;6.3 前置条件&quot;">​</a></h3><ul><li>review 意见有稳定 id（GitHub 内联评论锚点天然有）。</li><li>能拿到 PR 后续 commit 与 diff。</li><li>分类型统计的脚本（几十行即可）。</li></ul><h3 id="_6-4-适用边界" tabindex="-1">6.4 适用边界 <a class="header-anchor" href="#_6-4-适用边界" aria-label="Permalink to &quot;6.4 适用边界&quot;">​</a></h3><ul><li><strong>适用</strong>：有人类 maintainer 的团队仓库。</li><li><strong>半适用</strong>：纯个人项目——「采纳率」= 你改没改，跟另一个人讨论成本一样高，直接跳过这套机制。</li><li><strong>注意</strong>：改了代码 ≠ 认同意见（可能是自己先发现了、要赶时间、或者顺手重构）。所以这是<strong>代理指标</strong>，不能单独作为唯一优化目标。</li></ul><h3 id="_6-5-反例-失败模式" tabindex="-1">6.5 反例 / 失败模式 <a class="header-anchor" href="#_6-5-反例-失败模式" aria-label="Permalink to &quot;6.5 反例 / 失败模式&quot;">​</a></h3><ul><li><strong>用点赞 / LGTM 计数当效果</strong>。礼貌文化会直接污染这个信号，一票一个假阳性。</li><li><strong>把采纳率当唯一优化目标</strong>。Agent 会很快学会只提「一眼就对的建议」来刷分，意见总数暴跌，长期价值归零。要盯的是<strong>分类型采纳率</strong>而不是总采纳率。</li><li><strong>同一行反复修改导致重复计数</strong>。必须按（PR、行号、内容 hash）去重。</li><li><strong>静默当成认可</strong>——原文点名要拒绝的正是这个。</li></ul><h3 id="_6-6-可验证的效果指标" tabindex="-1">6.6 可验证的效果指标 <a class="header-anchor" href="#_6-6-可验证的效果指标" aria-label="Permalink to &quot;6.6 可验证的效果指标&quot;">​</a></h3><ul><li><p><strong>分类型采纳率</strong>。原文给了最有信息量的一组对照：<strong>【内部数据】</strong></p><table tabindex="0"><thead><tr><th>场景</th><th>意见采纳率</th><th>准确率</th></tr></thead><tbody><tr><td>回合补丁场景（一致性检查）</td><td>70.4%</td><td>99.8%</td></tr><tr><td>自研 PR 场景（代码质量审查）</td><td>41.8%</td><td>73.6%</td></tr></tbody></table><p>读法：差了近 30 个百分点。原因不是模型变笨了，而是**「可确定性判定」的意见采纳率天然远高于「开放式判断」的意见**。这个结论可以直接拿来指导资源分配——先把确定性检查做扎实，开放性问题先当提示而非门禁。</p></li><li><p><strong>置信度—采纳率曲线</strong>：按置信度分桶统计采纳率，找到「拦得住」的置信度阈值。</p></li><li><p><strong>静默率</strong>：被提出后完全无后续动作的意见占比。这是最容易被忽略的失败信号。</p></li></ul><h3 id="_6-7-原文逐字引用" tabindex="-1">6.7 原文逐字引用 <a class="header-anchor" href="#_6-7-原文逐字引用" aria-label="Permalink to &quot;6.7 原文逐字引用&quot;">​</a></h3><blockquote><p>「行为作证，拒绝自嗨——用户可能沉默，但代码变更骗不了人。」</p></blockquote><blockquote><p>「结合 Review 采纳率持续监控、知识更新、迭代校准与阈值调整，让 Agent 在真实使用中越用越准。」</p></blockquote><hr><h2 id="_7-共识提炼-·-ai-与人的三条信任边界" tabindex="-1">7. 共识提炼 · AI 与人的三条信任边界 <a class="header-anchor" href="#_7-共识提炼-·-ai-与人的三条信任边界" aria-label="Permalink to &quot;7. 共识提炼 · AI 与人的三条信任边界&quot;">​</a></h2><p>这三条不是 Kitta 独有，是社区跑出来的共识。原文原话可以直接贴进团队规范：</p><table tabindex="0"><thead><tr><th>原则</th><th>落地规则</th><th>谁来兜底</th></tr></thead><tbody><tr><td><strong>精准分级，克制打扰</strong></td><td>「对安全漏洞和破坏坚决拦截 CI 流程，这是底线；其余问题分级呈现、仅作提示，不过多占用开发者的注意力」</td><td>底线类由 CI 兜底，提示类由人自行判断</td></tr><tr><td><strong>行为作证，拒绝自嗨</strong></td><td>「不把开发者的默默无视当成认可，不看用户说什么，看&quot;代码改了什么&quot;」</td><td>数据兜底</td></tr><tr><td><strong>人类兜底，适时退场</strong></td><td>「AI 是探照灯，照亮风险、给出证据；Maintainer 是方向盘，最终决策权在人，是最后一道防线。」</td><td>人</td></tr></tbody></table><p>结语值得原样抄进团队 wiki：</p><blockquote><p>「最好的 AI 门禁，不是替代 Maintainer，而是让他们只把精力花在真正需要人类智慧的地方。」</p></blockquote><p>注意第三条和 <code>procurement-plan.md</code> 里「开发者为代码质量第一责任人」是同一件事的两种说法——<strong>门禁可以自动化，责任人不能自动化</strong>。</p><hr><h2 id="_8-个人-一人公司-agent-工作流降级做法" tabindex="-1">8. 个人 / 一人公司 / Agent 工作流降级做法 <a class="header-anchor" href="#_8-个人-一人公司-agent-工作流降级做法" aria-label="Permalink to &quot;8. 个人 / 一人公司 / Agent 工作流降级做法&quot;">​</a></h2><p>Kitta 的完整形态（专家资产管线 + 五阶段 + Benchmark + 线上评估框架）需要团队和内核仓库。<strong>个人版的目标是拿到这套方法 20% 左右的收益（编辑估计，原文无对应数据），成本从「人月」降到「一两天」。</strong></p><h3 id="_8-1-专家资产-→-两份文件" tabindex="-1">8.1 专家资产 → 两份文件 <a class="header-anchor" href="#_8-1-专家资产-→-两份文件" aria-label="Permalink to &quot;8.1 专家资产 → 两份文件&quot;">​</a></h3><p>放弃四步管线，直接手写：</p><ul><li><code>review-rubric.md</code>：从这个项目<strong>真实吵过架</strong>的历史里列 10–20 条判定标准（每条带一个例子）。</li><li><code>review-samples/</code>：20 条样本（15 条问题 + 5 条 LGTM），每条一句预期结论 + 一句理由。</li></ul><p>合计一晚上。这是原文专家资产的<strong>最小可运行形态</strong>——两类资产都保留了，只是靠手写而非管线产出。</p><h3 id="_8-2-五阶段-→-两阶段" tabindex="-1">8.2 五阶段 → 两阶段 <a class="header-anchor" href="#_8-2-五阶段-→-两阶段" aria-label="Permalink to &quot;8.2 五阶段 → 两阶段&quot;">​</a></h3><p>砍掉 Stage 3、4（没有回合场景），Stage 1 分类也可以并进去。个人版只保留：</p><ol><li><strong>规范检查</strong>：commit message 格式 / PR 描述是否写清「为什么改」（只提示，不拦截）。</li><li><strong>代码质量审查</strong>：按 §4 的子系统清单 + 行号/反例场景硬约束输出。</li></ol><p>挂在一个 GitHub Action 或 <code>pre-commit</code> hook 上。<strong>注意</strong>：个人仓库里没有第三方 reviewer，门禁意义有限，主要价值是「强制自己停顿一次」。</p><h3 id="_8-3-依赖链检查-→-手工-checklist" tabindex="-1">8.3 依赖链检查 → 手工 checklist <a class="header-anchor" href="#_8-3-依赖链检查-→-手工-checklist" aria-label="Permalink to &quot;8.3 依赖链检查 → 手工 checklist&quot;">​</a></h3><p>没有上游回合，但有等价场景：cherry-pick 修 bug、升级 vendored 依赖、抄开源代码、同步配置。每次做这类操作时，勾一遍：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>□ 这个改动依赖的其它改动，都带过来了吗？</span></span>
<span class="line"><span>□ 同一个上游修复（同一个 issue / 同一个 commit），是否还有其它 hunk？</span></span>
<span class="line"><span>□ 抄进来的代码，它的测试/配置/依赖声明是否也抄了？</span></span></code></pre></div><p>三条比自动化脚本有用——自动化要等到你一年抄 20 次才划算。</p><h3 id="_8-4-子系统知识库-有罪推定-→-目录级-checklist-输出约束" tabindex="-1">8.4 子系统知识库 + 有罪推定 → 目录级 checklist + 输出约束 <a class="header-anchor" href="#_8-4-子系统知识库-有罪推定-→-目录级-checklist-输出约束" aria-label="Permalink to &quot;8.4 子系统知识库 + 有罪推定 → 目录级 checklist + 输出约束&quot;">​</a></h3><ul><li>知识库：每个顶层目录一份 <code>checklist.md</code>，3–5 条就够。</li><li>自我辩论降级为<strong>输出格式硬约束</strong>：每条结论必须给 <code>文件:行号</code> + <code>触发反例</code>；给不出就不许输出这一条。</li><li>确定性可判的（编译、类型、lint）<strong>交给工具</strong>，只让模型负责语义判断。这是最重要的一条省钱原则。</li></ul><h3 id="_8-5-验证样本-→-20-条金标准-放在-ci-里" tabindex="-1">8.5 验证样本 → 20 条金标准，放在 CI 里 <a class="header-anchor" href="#_8-5-验证样本-→-20-条金标准-放在-ci-里" aria-label="Permalink to &quot;8.5 验证样本 → 20 条金标准，放在 CI 里&quot;">​</a></h3><p>每次改 prompt 跑一遍，20 条 × 1 分钟内出结果。样本 &lt; 20 条时分数波动大，但足以回答「这次改动是变好还是变坏」这个唯一重要的问题。</p><h3 id="_8-6-行为作证-→-一行-git-命令" tabindex="-1">8.6 行为作证 → 一行 git 命令 <a class="header-anchor" href="#_8-6-行为作证-→-一行-git-命令" aria-label="Permalink to &quot;8.6 行为作证 → 一行 git 命令&quot;">​</a></h3><p>不需要评估框架。review 评论发出后 7 天，看那几行有没有被改过：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since=7.days</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&lt;行号上下文&gt;&#39;</span></span></code></pre></div><p>采纳率手动记在一个 md 表里即可。个人仓库没有统计价值，但<strong>有一个真实价值</strong>：它会逼你发现「哪些意见你自己都不当回事」——那些就该从 rubric 里删掉。</p><h3 id="_8-7-时间表与预算" tabindex="-1">8.7 时间表与预算 <a class="header-anchor" href="#_8-7-时间表与预算" aria-label="Permalink to &quot;8.7 时间表与预算&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>投入</th><th>产出</th></tr></thead><tbody><tr><td>第 1 天</td><td>2–3 小时</td><td><code>review-rubric.md</code> + 20 条样本</td></tr><tr><td>第 2 天</td><td>2–3 小时</td><td>CI Action（两阶段）+ 输出格式约束</td></tr><tr><td>第 2–3 周</td><td>每次 PR 自动跑</td><td>10 个 PR 的第一组自有数据：采纳率、误报率、耗时</td></tr><tr><td>第 4 周</td><td>1 小时</td><td>按数据收窄触发条件，删掉没人当回事的意见</td></tr></tbody></table><p><strong>明确不要做的</strong>：不要自建向量库、不要复刻五阶段、不要训模型、不要为了「看起来专业」写复杂的多 agent 编排。原文自己都把结论落在「沉淀专家资产 + 定制审查流程 + 评测闭环」这三件朴素的事上。</p><hr><h2 id="_9-反模式清单-可直接贴进-contributing-md-pr-模板" tabindex="-1">9. 反模式清单（可直接贴进 CONTRIBUTING.md / PR 模板） <a class="header-anchor" href="#_9-反模式清单-可直接贴进-contributing-md-pr-模板" aria-label="Permalink to &quot;9. 反模式清单（可直接贴进 CONTRIBUTING.md / PR 模板）&quot;">​</a></h2><blockquote><p>任何一条踩中，这次 review 的产出就不该被信任：</p></blockquote><ol><li>没有项目级评判标准，只跑了通用 lint / 通用 checklist 就叫「AI 评审」——那是工具调用，不是领域定制。</li><li>一份巨大清单里塞满通用最佳实践，没有一条来自本仓库的真实历史。</li><li>所有问题同一优先级，<code>Critical</code> 被淹没在 30 条提示里。</li><li>报告里的问题定位不到具体代码行。</li><li>只检查「这次改了什么」，不检查「该带什么」（回合 / backport / 抄代码场景）。</li><li>把「逐行都对」当成语义一致。</li><li>没有验证样本，改 prompt 全靠「感觉更聪明了」。</li><li>拿优化样本当评测集，分数虚高还拿来汇报。</li><li>用点赞 / LGTM 计数当效果指标。</li><li>把静默当认可，据此放宽阈值。</li><li>让 LLM 去判断能否编译、类型是否匹配这类确定性问题。</li><li>允许模型输出没有行号、没有触发场景的缺陷结论。</li><li>rubric 只增不减，半年后一半条目已被代码改动作废。</li><li>把 AI 门禁当成对人的替代——原文的底线是「最终决策权在人」。</li></ol><hr><h2 id="_10-一句话操作流-给-agent-用" tabindex="-1">10. 一句话操作流（给 Agent 用） <a class="header-anchor" href="#_10-一句话操作流-给-agent-用" aria-label="Permalink to &quot;10. 一句话操作流（给 Agent 用）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>On PR opened (or comment \`/check-code-review\`):</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>[1] CLASSIFY            规则：commit msg 含 \`commit xxx upstream\` / Fixes: 标签？</span></span>
<span class="line"><span>      ├─ 回合/backport → 走 [3][4]</span></span>
<span class="line"><span>      └─ 自研         → 跳过 [3][4]</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>[2] HYGIENE            PR 描述 / commit title / message 规范</span></span>
<span class="line"><span>      无问题 → 不输出任何评论（沉默是默认态）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>[3] DEPENDENCY CLOSURE  检索上游 Fixes → 是否在本 PR → 是否已在下游存在</span></span>
<span class="line"><span>      输出三选一：无遗漏 / 已合入(指 commit) / 遗漏(要求补充)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>[4] CONSISTENCY        基础对比(文件/代码块) → 上下文对比(符号/适配) → 语义对比(LLM)</span></span>
<span class="line"><span>      标签：consistent | text-inconsistent | semantic-inconsistent | inconsistent</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>[5] CODE QUALITY        加载子目录 checklist</span></span>
<span class="line"><span>      缺陷推理：有罪推定 → 沿调用链追语义 → 自我辩论</span></span>
<span class="line"><span>      硬约束：每条结论必须带 file:line + 可触发的反例场景，否则丢弃</span></span>
<span class="line"><span>      分级：Critical（内联到行） / Medium·Low（汇总） / 无风险 → LGTM</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Post inline comments（每条带 stable id）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>On every subsequent commit/push:</span></span>
<span class="line"><span>  回查 stable id 对应行是否被修改 → 更新分类型采纳率 → 调阈值</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Nightly: 验证样本隔离评测（precision/recall）→ 与线上采纳率交叉验证</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>BLOCK merge only if: 安全漏洞 or 破坏性变更（且置信度高于熔断阈值）</span></span></code></pre></div><p><strong>与原文的差异（有意为之）</strong>：原文在 CI 顶部就有独立的「智能化测试」环节；个人/小团队应把本文这条链路接在自己的测试之上，而不是替代它。</p><hr><h2 id="_11-原文数据的可核实性分级" tabindex="-1">11. 原文数据的可核实性分级 <a class="header-anchor" href="#_11-原文数据的可核实性分级" aria-label="Permalink to &quot;11. 原文数据的可核实性分级&quot;">​</a></h2><p>引用本文任何数字前，先看这张表。<strong>分不清等级的数字不要写进对外材料。</strong></p><table tabindex="0"><thead><tr><th>数据</th><th>数值</th><th>等级</th><th>备注</th></tr></thead><tbody><tr><td>DORA：Bug 率 / 评审时间 / PR 体积</td><td>+9% / +91% / +154%</td><td><strong>【外部可核实】</strong></td><td>原文自注「受访者约 5,000 人，数字为相关性口径而非因果结论」——是相关性，不是「AI 导致」</td></tr><tr><td>全行业 CVE 同比</td><td>全部 +394%，高危 +811%</td><td><strong>【外部可核实】</strong></td><td>来源 Linux Foundation《The CRA Readiness Reality: What Changed and What Didn&#39;t Between 2025 and 2026》</td></tr><tr><td>Linux 内核各版本 CVE 修复数</td><td>6.9–6.19 约四五百 → 7.0 约 1250 → 7.2 近 1900</td><td><strong>【外部可核实】</strong></td><td>来自上游统计，可自行核对</td></tr><tr><td>累计审查规模</td><td>7 万+ 补丁</td><td><strong>【内部数据】</strong></td><td>龙蜥社区生产环境</td></tr><tr><td>门禁准确率</td><td>97%</td><td><strong>【内部数据】</strong></td><td>口径与下面的场景准确率不同，勿混用</td></tr><tr><td>代码合入率</td><td>62%</td><td><strong>【内部数据】·口径未定义</strong></td><td>原文未说明分母（全部提交？已触发审查的？），不可直接引用</td></tr><tr><td>回合补丁一致性检查</td><td>采纳率 70.4%、准确率 99.8%</td><td><strong>【内部数据】</strong></td><td>基于已合入 PR 的回溯统计</td></tr><tr><td>自研 PR 代码质量意见</td><td>采纳率 41.8%、准确率 73.6%</td><td><strong>【内部数据】</strong></td><td>同上；这个数字是全文最诚实的一个</td></tr><tr><td>六大领域审查质量提升</td><td>17.0%–31.6%（明细见下表）</td><td><strong>【内部数据】·基线未定义</strong></td><td>原文未说明「提升」相对什么基线、用什么度量</td></tr><tr><td>「四阶段遗漏 Fixes 检索流程」</td><td>—</td><td><strong>口径不一致</strong></td><td>§3.1 称四阶段，Stage 3 正文只展开三步</td></tr><tr><td>数据飞轮（反哺千问基座）</td><td>四类数据 → 四项能力</td><td><strong>【内部主张】</strong></td><td>属团队战略叙述，非可验证指标</td></tr></tbody></table><p>六大领域明细（原文原表，<strong>基线与度量均未定义</strong>，仅供量级参考）：</p><table tabindex="0"><thead><tr><th>领域</th><th>审查质量提升</th><th>领域</th><th>审查质量提升</th></tr></thead><tbody><tr><td>操作系统内核</td><td>20.4%</td><td>网络系统</td><td>19.8%</td></tr><tr><td>编译器</td><td>24.4%</td><td>云原生平台</td><td>31.6%</td></tr><tr><td>文件系统</td><td>17.0%</td><td>AI 计算框架</td><td>21.7%</td></tr></tbody></table><p>一句话：<strong>这份材料适合用来学方法，不适合用来引用数字。</strong></p><hr><h2 id="_12-参考" tabindex="-1">12. 参考 <a class="header-anchor" href="#_12-参考" aria-label="Permalink to &quot;12. 参考&quot;">​</a></h2><ul><li>原文：<a href="https://raw.githubusercontent.com/aliyun/ai-agent-handbook/HEAD/06-case-study/%E7%AC%AC25%E7%AB%A0%20%E7%A0%94%E5%8F%91%E6%95%88%E8%83%BD/Kitta%EF%BC%9A%E9%A2%86%E5%9F%9F%E4%B8%93%E7%94%A8%20Code%20Review%20Agent.md" target="_blank" rel="noreferrer">aliyun/ai-agent-handbook 第 25 章 · Kitta：领域专用 Code Review Agent</a></li><li>站内串联：<a href="./procurement-plan.html">procurement-plan 采购与实施方案</a>（成本与责任红线）· <a href="./reporter.html">reporter Vibe Coding 报告</a>（行业判断）· <a href="https://github.com/zenHeart/learn-ai/blob/master/docs/practice/ai-efficiency-practice.md" target="_blank" rel="noreferrer">ai-efficiency-practice 跨平台提效实践</a>（AI 覆盖全链路的另一视角）· <a href="./">index 企业实践目录</a></li><li>建议同节并列的姊妹页：ABACI 内核质量门禁（定向测试与缺陷模式复用）——「该不该合」与「有没有被验证过」是一对。</li><li>第三方报告（可自行核对）：DORA《State of AI-assisted Software Development》· Linux Foundation《The CRA Readiness Reality: What Changed and What Didn&#39;t Between 2025 and 2026》</li><li>原文声明：「本文档为技术能力介绍材料，文中数据来源于内部评测与生产环境统计。」</li></ul>`,194)])])}const m=a(r,[["render",n]]);export{k as __pageData,m as default};
